from typing import List

def validateBinaryTreeNodes(n: int, leftChild: List[int], rightChild: List[int]) -> bool:
    parents = [-1] * n
    for i in range(n):
        for child in [leftChild[i], rightChild[i]]:
            if child != -1:
                if parents[child] != -1:
                    return False
                parents[child] = i
    return sum(p != -1 for p in parents) == n - 1
